+    private static String readLine(InputStream is) throws IOException {
+        ByteArrayOutputStream os = new ByteArrayOutputStream();
+        while (true) {
+            int b = is.read();
+            if (b == -1) {
+                break;
+            }
+            if (b == '\r') {
+                if (is.read() != '\n') {
+                    throw new IllegalStateException("Not CRLF");
+                }
+                break;
+            }
+            os.write(b);
+        }
+        return os.toString(ISO_8859_1);
+    }
+}
